try:
    import torch
    import torch.nn as nn
except ImportError:
    torch = None

if torch is not None:
    class SimpleCNN(nn.Module):
        def __init__(self):
            super().__init__()
            self.conv1 = nn.Conv2d(1, 32, 3, padding=1)
            self.conv2 = nn.Conv2d(32, 64, 3, padding=1)
            self.pool = nn.MaxPool2d(2, 2)
            self.relu = nn.ReLU()
            self.fc = nn.Linear(64 * 7 * 7, 10)

        def forward(self, x):
            x = self.pool(self.relu(self.conv1(x)))
            x = self.pool(self.relu(self.conv2(x)))
            x = torch.flatten(x, 1)
            return self.fc(x)

    model = SimpleCNN()
    X = torch.randn(4, 1, 28, 28)  # batch of 4 images
    output = model(X)
    print(f'Output shape: {output.shape}')
else:
    # torch is not available in this environment: same architecture in numpy
    import numpy as np
    from numpy.lib.stride_tricks import sliding_window_view

    class Size(tuple):
        def __repr__(self):
            return f"torch.Size({list(self)})"
        __str__ = __repr__

    class SimpleCNN:
        def __init__(self):
            rng = np.random.default_rng(0)
            self.w1 = rng.standard_normal((32, 1, 3, 3)) * 0.1
            self.b1 = np.zeros(32)
            self.w2 = rng.standard_normal((64, 32, 3, 3)) * 0.05
            self.b2 = np.zeros(64)
            self.wf = rng.standard_normal((10, 64 * 7 * 7)) * 0.02
            self.bf = np.zeros(10)

        @staticmethod
        def conv(x, w, b):
            xp = np.pad(x, ((0, 0), (0, 0), (1, 1), (1, 1)))
            win = sliding_window_view(xp, (3, 3), axis=(2, 3))
            return np.einsum('nchwij,ocij->nohw', win, w) + b[None, :, None, None]

        @staticmethod
        def pool(x):
            n, c, h, w = x.shape
            return x.reshape(n, c, h // 2, 2, w // 2, 2).max(axis=(3, 5))

        def __call__(self, x):
            x = self.pool(np.maximum(self.conv(x, self.w1, self.b1), 0))
            x = self.pool(np.maximum(self.conv(x, self.w2, self.b2), 0))
            x = x.reshape(x.shape[0], -1)
            return x @ self.wf.T + self.bf

    model = SimpleCNN()
    X = np.random.randn(4, 1, 28, 28)  # batch of 4 images
    output = model(X)
    print(f'Output shape: {Size(output.shape)}')
